-- Replace only the original CMS defaults used by the Home sections.
UPDATE site_content AS content
SET value = replacement.new_value,
    label = CASE WHEN content.label = replacement.old_label
                 THEN replacement.new_label ELSE content.label END
FROM (VALUES
  ('home.attributes-011', '{"data-alt":"Panoramic overhead view of Nha Trang crescent bay with azure sea water, golden sandy beach lined with green palm trees and luxury skyscrapers","backgroundImage":"url(''/images/07eaa0892315c5ca.jpg'')"}'::jsonb, '{"data-alt":"Toàn cảnh bờ biển Nha Trang","backgroundImage":"url(''/images/figma/home/destination-nha-trang.webp'')"}'::jsonb, 'Panoramic overhead view of Nha Trang crescent bay with azure sea water, golden sandy beach lined with green palm trees and luxury skyscrapers · url(''/', 'Toàn cảnh bờ biển Nha Trang'),
  ('home.attributes-013', '{"data-alt":"Da Lat pine hills morning mist Xuan Huong Lake tranquil peaceful nature scenery Vietnam","backgroundImage":"url(''/images/c394838ce599ce62.jpg'')"}'::jsonb, '{"data-alt":"Nhà thờ và thành phố Đà Lạt từ trên cao","backgroundImage":"url(''/images/figma/home/destination-da-lat.webp'')"}'::jsonb, 'Da Lat pine hills morning mist Xuan Huong Lake tranquil peaceful nature scenery Vietnam · url(''/images/c394838ce599ce62.jpg'')', 'Nhà thờ và thành phố Đà Lạt từ trên cao'),
  ('home.attributes-015', '{"data-alt":"Da Nang Dragon Bridge over Han river and My Khe beach coastline luxury resorts","backgroundImage":"url(''/images/391c9adc5fa131a2.jpg'')"}'::jsonb, '{"data-alt":"Cầu Vàng ở Đà Nẵng","backgroundImage":"url(''/images/figma/home/destination-da-nang.webp'')"}'::jsonb, 'Da Nang Dragon Bridge over Han river and My Khe beach coastline luxury resorts · url(''/images/391c9adc5fa131a2.jpg'')', 'Cầu Vàng ở Đà Nẵng'),
  ('home.attributes-017', '{"data-alt":"Phu Quoc island tropical coast with traditional fishing boats floating on clear emerald sea water","backgroundImage":"url(''/images/f1eb07f99dded4ba.jpg'')"}'::jsonb, '{"data-alt":"Khu phố ven biển Phú Quốc","backgroundImage":"url(''/images/figma/home/destination-phu-quoc.webp'')"}'::jsonb, 'Phu Quoc island tropical coast with traditional fishing boats floating on clear emerald sea water · url(''/images/f1eb07f99dded4ba.jpg'')', 'Khu phố ven biển Phú Quốc'),
  ('home.attributes-019', '{"data-alt":"Sapa terraced rice fields in golden harvest season under misty Fansipan mountains","backgroundImage":"url(''/images/d1b9b15bb6269830.jpg'')"}'::jsonb, '{"data-alt":"Mái ngói phố cổ Hội An","backgroundImage":"url(''/images/figma/home/destination-hoi-an.webp'')"}'::jsonb, 'Sapa terraced rice fields in golden harvest season under misty Fansipan mountains · url(''/images/d1b9b15bb6269830.jpg'')', 'Mái ngói phố cổ Hội An'),
  ('home.text-110', '"Biển đẹp, trung tâm sôi động, nhiều lựa chọn nghỉ dưỡng"'::jsonb, '"Thiên đường biển xanh"'::jsonb, 'Biển đẹp, trung tâm sôi động, nhiều lựa chọn nghỉ dưỡng', 'Thiên đường biển xanh'),
  ('home.text-113', '"Khí hậu mát mẻ, homestay thơ mộng"'::jsonb, '"Thành phố ngàn hoa"'::jsonb, 'Khí hậu mát mẻ, homestay thơ mộng', 'Thành phố ngàn hoa'),
  ('home.text-116', '"Biển Mỹ Khê & trung tâm sầm uất"'::jsonb, '"Nhịp sống sôi động"'::jsonb, 'Biển Mỹ Khê & trung tâm sầm uất', 'Nhịp sống sôi động'),
  ('home.text-119', '"Resort biển đảo phù hợp gia đình"'::jsonb, '"Đảo ngọc nghỉ dưỡng"'::jsonb, 'Resort biển đảo phù hợp gia đình', 'Đảo ngọc nghỉ dưỡng'),
  ('home.text-121', '"Sapa"'::jsonb, '"Hội An"'::jsonb, 'Sapa', 'Hội An'),
  ('home.text-122', '"Núi rừng, ruộng bậc thang kỳ vĩ"'::jsonb, '"Phố cổ lung linh"'::jsonb, 'Núi rừng, ruộng bậc thang kỳ vĩ', 'Phố cổ lung linh'),
  ('home.text-166', '"\n          Bạn muốn hợp tác cùng {{brand.name}}?\n        "'::jsonb, '"Nhận ưu đãi từ {{brand.name}}"'::jsonb, 'Bạn muốn hợp tác cùng {{brand.name}}?', 'Nhận ưu đãi từ {{brand.name}}'),
  ('home.text-167', '"\n          Chúng tôi hỗ trợ kết nối hơn 500+ khách sạn, resort, đối tác tour lữ hành và nhà xe đến hàng triệu du khách trên cả nước. Để lại thông tin hoặc nhắn Zalo để chuyên viên liên hệ ngay.\n        "'::jsonb, '"Khám phá khách sạn, tour và combo cho kỳ nghỉ của bạn."'::jsonb, 'Chúng tôi hỗ trợ kết nối hơn 500+ khách sạn, resort, đối tác tour lữ hành và nhà xe đến hàng triệu du khách trên cả nước. Để lại thông tin hoặc nhắn Z', 'Khám phá khách sạn, tour và combo cho kỳ nghỉ của bạn.'),
  ('footer.text-025', '"{{brand.name}}"'::jsonb, '"Nền tảng đặt phòng, tour du lịch và trải nghiệm hằng ngày tại Nha Trang."'::jsonb, '{{brand.name}}', 'Nền tảng đặt phòng, tour du lịch và trải nghiệm hằng ngày tại Nha Trang.')
) AS replacement(key, old_value, new_value, old_label, new_label)
WHERE content.key = replacement.key
  AND content.value = replacement.old_value;
